        if max_calls <= 0 or period_seconds <= 0:
            return None
        self.max_calls = max_calls
        self.period_seconds = period_seconds
        self.tokens = []
        self.last_reset = 0

    def allow(self, timestamp: float) -> bool:
        if timestamp <= 0:
            return None
        self._reset_tokens(timestamp)
        if len(self.tokens) < self.max_calls:
            self.tokens.append(timestamp)
            return True
        return False

