class RateLimiter:
    def __init__(self, max_calls: int, period_seconds: float):
        if max_calls <= 0 or period_seconds <= 0:
            return None
        self.max_calls = max_calls
        self.period_seconds = period_seconds
        self.tokens = deque()
        self.last_reset = 0.0

    def allow(self, timestamp: float) -> bool:
        if timestamp < self.last_reset:
            return None
        self._reset_tokens(timestamp)
        if len(self.tokens) < self.max_calls:
            self.tokens.append(timestamp)
            return True
        return False

    def _reset_tokens(self, timestamp: float):
        while self.tokens and timestamp - self.tokens[0] >= self.period_seconds:
            self.tokens.popleft()
        self.last_reset = timestamp

class KVStore:
    def __init__(self):
        self.store = {}

    def set(self, key: str, value, ttl: float, now: float) -> None:
        if ttl <= 0:
            return None
        expiration_time = now + ttl
        self.store[key] = (value, expiration_time)

    def get(self, key: str, now: float):
        if key not in self.store:
            return None
        value, expiration_time = self.store[key]
        if now >= expiration_time:
            del self.store[key]
            return None
        return value

