    max_freq_tasks = sum(1 for count in task_count.values() if count == max_freq)

    # Calculate the minimum intervals needed
    partitions = max_freq - 1
    empty_slots = partitions * (n - (max_freq_tasks - 1))
    available_tasks = len(tasks) - max_freq * max_freq_tasks
    idle_slots = max(0, empty_slots - available_tasks)

    total_time = (max_freq * (n + 1)) - idle_slots

    return max(len(tasks), total_time)

